const queue = [...($json.folderQueue || [])];
const current = queue.shift();
if (!current) return [{ json: { ...$json, currentFolderId: null, currentFolder: null, folderQueue: queue } }];
return [{ json: { ...$json, currentFolderId: current.id, currentFolder: current, folderQueue: queue } }];

function isYearFolder(name) {
  return /^(19|20)\d{2}$/.test(String(name || '').trim());
}

const current = $('Preparar carpeta').first().json;
const parent = current.currentFolder || { drive_path: '', category_path: [] };
const folders = Array.isArray($json.files) ? $json.files : [];
const folderRows = folders.map((folder) => {
  const name = String(folder.name || '').trim();
  const isCategoryFolder = !isYearFolder(name);
  const categoryPath = isCategoryFolder ? [...(parent.category_path || []), name] : [...(parent.category_path || [])];
  const drivePath = [parent.drive_path, name].filter(Boolean).join('/');
  return {
    drive_id: folder.id,
    name,
    mime_type: folder.mimeType || 'application/vnd.google-apps.folder',
    parent_drive_id: current.currentFolderId,
    drive_path: drivePath,
    category_path: categoryPath,
    is_category_folder: isCategoryFolder,
    modified_time: folder.modifiedTime || null,
    web_view_link: folder.webViewLink || null,
  };
});
const childQueue = folderRows.map((row) => ({
  id: row.drive_id,
  name: row.name,
  drive_path: row.drive_path,
  category_path: row.category_path,
}));
return [{ json: { ...current, folderRows, childQueue } }];
